import {BANKS,MODES,TYPES,CREDENTIAL_LABELS,newBanking,ensureBanking,preparation,validateDraft,normalizeTaxId,publicConfiguration,RESEARCH_DATE} from './banking-model.js?v=17';

export function createBanking(a){
  const {esc,btn,icon,pill,panel,empty,link}=a;
  const owned=id=>a.scope('accounts').find(x=>x.id===id);
  const option=(value,label,selected)=>`<option value="${esc(value)}" ${value===String(selected)?'selected':''}>${esc(label)}</option>`;
  const input=(label,path,value,type='text',extra='')=>`<label>${label}<input data-bank-field="${path}" name="${path}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const select=(label,path,value,choices,extra='')=>`<label>${label}<select data-bank-field="${path}" name="${path}" aria-label="${esc(label)}" ${extra}>${Object.entries(choices).map(([v,l])=>option(v,l,value)).join('')}</select></label>`;
  const source=(url,label)=>`<a class="textbtn bank-source" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
  function page(){ensureBanking(a.state);const accounts=a.scope('accounts');return a.titleBlock('Contas e bancos','O extrato encontra as obrigações. Os documentos completam a história.',btn('Cadastrar conta','data-open="bank-account"','primary','plus'),'Conexões da empresa')+`
    <div class="bank-intro"><div><span class="eyebrow">Bradesco + Banco do Brasil</span><h2>Uma rotina. Dois bancos.</h2><p>Identifique suas contas, escolha como os movimentos chegarão e organize o que ainda precisa de conferência.</p></div><span class="bank-demo-tag">${icon('lock')} Configuração de prévia<br><small>Nenhuma conexão ativa</small></span></div>
    <div class="bank-card-grid">${accounts.map(x=>{const c=x.banking,b=BANKS[c.bankCode],tasks=a.scope('tasks').filter(t=>t.bankAccount===x.id&&!t.done);return `<article class="bank-card"><div class="bank-card-top"><span class="bank-monogram bank-${c.bankCode}">${esc(b?.short||'—')}</span>${pill('Não conectado','amber')}</div><h2>${esc(x.name)}</h2><p>${esc(x.label)}</p><dl><div><dt>Agência / conta</dt><dd>${c.branch?esc(c.branch+(c.branchDigit?'-'+c.branchDigit:'')):'A informar'} / ${c.number?esc('••••'+c.number.slice(-3)+(c.digit?'-'+c.digit:'')):'A informar'}</dd></div><div><dt>Forma de entrada</dt><dd>${MODES[c.mode]}</dd></div><div><dt>Última atualização bancária</dt><dd>Nenhuma consulta realizada</dd></div></dl><div class="bank-card-bottom"><small>${tasks.length?tasks.length+' tarefa(s) pendente(s)':'Cadastro independente do saldo de exemplo'}</small>${btn('Configurar',`data-open="bank-account" data-id="${esc(x.id)}"`,'','chevron')}</div></article>`}).join('')}</div>
    ${panel('Do banco ao documento','Cada etapa resolve uma pergunta diferente.',`<div class="bank-journey"><div><b>01</b><h3>Movimento recebido</h3><p>Data, valor, conta e identificação de origem. Futuro e efetivado separados.</p></div><div><b>02</b><h3>Obrigação relacionada</h3><p>Associe contrato, parcela ou ativo. Confira recebimentos parciais e rateios.</p></div><div><b>03</b><h3>Comprovante conferido</h3><p>O lançamento no extrato não substitui recibos e documentos de origem.</p></div></div>`)}
    <div class="bank-options"><article><h3>${icon('file')} Arquivo do banco</h3><p>OFX como primeira opção; CSV com formato ajustável. O leitor será validado com uma amostra de cada conta.</p></article><article><h3>${icon('link')} API de cada banco</h3><p>Consulta de contas próprias PJ, mediante habilitação, aplicação e certificado. Regras específicas para cada banco.</p></article><article><h3>${icon('company')} Open Finance</h3><p>Alternativa por parceiro e instituição receptora, com autorização no banco e controle de consentimento.</p></article></div>
    <div class="callout">${icon('info')}<span>Você pode salvar e exportar o cadastro nesta prévia. Consulta bancária, leitura de extratos e atualização agendada dependem da implementação dos conectores. Use dados de teste neste navegador.</span></div>
    <details class="bank-research"><summary>Referências oficiais · consultadas em 12/11/2026</summary><div>${source(BANKS['237'].source,'Bradesco · Saldo e extrato')}${source(BANKS['237'].authSource,'Bradesco · autenticação mTLS')}${source(BANKS['001'].source,'BB · Extratos v2')}${source('https://bcb.gov.br/meubc/faqs/s/open-finance','Banco Central · Open Finance')}</div><p>Versões, condições e habilitação devem ser reconfirmadas antes da entrada em produção.</p></details>`}
  function draft(){const cur=a.current;if(!cur.bankDraft){const x=owned(cur.id);cur.bankDraft={label:x?.label||'',config:structuredClone(x?.banking||newBanking()),tab:'identity'}}return cur.bankDraft}
  function capture(form=document.querySelector('form[data-form="bank-account"]')){if(!form)return;const d=draft();for(const el of form.querySelectorAll('[data-bank-field]')){const path=el.dataset.bankField;if(path==='label'){d.label=el.value;continue}const keys=path.split('.');let obj=d.config;for(const k of keys.slice(0,-1))obj=obj[k];obj[keys.at(-1)]=el.type==='number'?Number(el.value):el.value}}
  function identity(d,x){const c=d.config;return `<div class="bank-form-heading"><h3>Identidade da conta</h3><p>A conta pertence à empresa selecionada. Os dígitos ficam separados do número.</p></div>${input('Nome para identificar a conta','label',d.label,'text','maxlength="80" placeholder="Ex.: Recebimentos de aluguéis" required')}${select('Banco','bankCode',c.bankCode,{'':'Selecione','237':'237 · Bradesco','001':'001 · Banco do Brasil'},x&&BANKS[x.banking.bankCode]?'disabled':'')}<div class="formrow">${input('Agência sem dígito','branch',c.branch,'text','inputmode="numeric" maxlength="6"')}${input('Dígito da agência','branchDigit',c.branchDigit,'text','maxlength="2"')}</div><div class="formrow">${input('Conta sem dígito','number',c.number,'text','inputmode="numeric" maxlength="20"')}${input('Dígito da conta','digit',c.digit,'text','maxlength="2"')}</div><div class="formrow">${select('Tipo de conta','type',c.type,TYPES)}${select('Titular','holderType',c.holderType,{PJ:'Pessoa jurídica',PF:'Pessoa física'})}</div>${input('Nome / razão social do titular','holderName',c.holderName,'text','maxlength="120"')}${input(c.holderType==='PJ'?'CNPJ do titular':'CPF do titular','taxId',c.taxId,'text','maxlength="18"')}<p class="annotation">BRL · CNPJ aceita formato alfanumérico. A checagem de formato não comprova titularidade ou situação cadastral.</p>`}
  function apiFields(c){const b=BANKS[c.bankCode],env=c.environment,e=c.environments[env],p='environments.'+env+'.';if(!b)return '<p class="callout">Escolha o banco na aba Conta.</p>';
    return `<div class="bank-product"><span>${pill(b.product,'green')}</span><p>${c.bankCode==='001'?'Contas correntes próprias PJ. Usar v2; a documentação prevê desligar v1 em 20/11/2026.':'Contas correntes e poupança PJ. Conta corrente e Invest Fácil têm visões diferentes.'}</p></div><div class="formrow">${select('Ambiente','environment',env,{sandbox:'Testes / homologação',production:'Produção'})}${select('Habilitação neste ambiente',p+'approval',e.approval,{'not-requested':'Ainda não solicitada',requested:'Solicitada ao banco',declared:'Habilitada — informação manual'})}</div>${input('Nome da aplicação no portal do banco',p+'application',e.application,'text','maxlength="100"')}
    ${c.bankCode==='237'?select('Visão do saldo e extrato','bradesco.operation',c.bradesco.operation,{'1':'Conta corrente separada do Invest Fácil','2':'Conta corrente + Invest Fácil (unificado)'})+'<p class="annotation">Aplicações e resgates precisam ser identificados como transferências; não devem virar receita ou despesa automaticamente.</p>':''}
    <details class="bank-advanced"><summary>Credenciais e detalhes da integração</summary><p>Informe apenas nomes de referência para o armazenamento seguro do servidor, no formato <code>ref:nome</code>. Os valores reais serão configurados fora desta prévia.</p>${b.credentials.map(key=>input('Referência · '+CREDENTIAL_LABELS[key],p+key,e[key],'text','maxlength="55" placeholder="ref:nome-no-servidor" autocomplete="off"')).join('')}${input('Validade do certificado',p+'certificateExpires',e.certificateExpires,'date')}${c.bankCode==='001'?`${input('Registros por página','bb.pageSize',c.bb.pageSize,'number','min="30" max="120"')}${env==='sandbox'?input('MCI do cenário de teste BB',p+'testMci',e.testMci,'text','inputmode="numeric" maxlength="20"')+'<small>Obtido nos cenários oficiais do BB; não é enviado em produção.</small>':''}`:'<p class="annotation">Certificado A1 conforme regras do Bradesco; certificado e chave privada precisam corresponder às credenciais deste ambiente.</p>'}<dl class="bank-technical"><div><dt>API</dt><dd>${b.version}</dd></div><div><dt>Autenticação</dt><dd>OAuth 2 · client_credentials + mTLS${b.scope?' · '+b.scope:''}</dd></div><div><dt>Endereço de autenticação</dt><dd><code>${b.tokenUrls?.[env]||b.bases[env]+b.tokenPath}</code></dd></div><div><dt>Consulta de extrato</dt><dd><code>${b.bases[env]+b.statementPath}</code></dd></div><div><dt>Consulta por período</dt><dd>${c.bankCode==='001'?'Até 31 dias; paginação de 30 a 120 registros; histórico até 5 anos.':'Até um ano por consulta; limite de 5.000 transações; histórico até 10 anos. Ao atingir o limite, subdividir e conferir completude.'}</dd></div></dl>${source(b.source,'Documentação oficial')}${source(b.authSource,'Habilitação e autenticação')}</details>`;
  }
  function connection(c){return `<div class="bank-form-heading"><h3>Como os movimentos vão chegar?</h3><p>As três opções compartilham a mesma conta e o mesmo processo de conferência.</p></div><div class="bank-mode-choices">${Object.entries(MODES).map(([key,label])=>`<button type="button" data-bank-mode="${key}" class="${c.mode===key?'active':''}" aria-pressed="${c.mode===key}">${icon(key==='file'?'file':key==='api'?'link':'company')}<b>${label}</b></button>`).join('')}</div>${c.mode==='api'?apiFields(c):c.mode==='openfinance'?`<div class="callout">${icon('lock')}<span>A autorização será feita no banco, pelo parceiro escolhido. Esta tela não pede senha bancária nem cria um consentimento.</span></div>${input('Parceiro de integração','openfinance.provider',c.openfinance.provider,'text','maxlength="120" placeholder="A selecionar"')}${input('Instituição receptora dos dados','openfinance.recipient',c.openfinance.recipient,'text','maxlength="120"')}${input('Referência do consentimento','openfinance.consentReference',c.openfinance.consentReference,'text','maxlength="120"')}${input('Validade informada do consentimento','openfinance.consentExpires',c.openfinance.consentExpires,'date')}<p class="annotation">Escopo planejado: contas, saldos e transações. Consentimento, revogação e expiração devem ser confirmados pelo parceiro; preencher estes campos não autoriza acesso.</p>${source('https://bcb.gov.br/meubc/faqs/s/open-finance','Como funciona o Open Finance')}`:`${select('Formato preferido do extrato','file.format',c.file.format,{OFX:'OFX',CSV:'CSV'})}<p class="annotation">Prefira o extrato estruturado disponibilizado pelo banco. PDF e imagens continuam no acervo documental.</p>${c.file.format==='CSV'?`<div class="formrow">${select('Codificação','file.encoding',c.file.encoding,{auto:'Detectar e conferir','UTF-8':'UTF-8','Windows-1252':'Windows-1252'})}${select('Separador das colunas','file.separator',c.file.separator,{auto:'Detectar e conferir',';':'Ponto e vírgula',',':'Vírgula',tab:'Tabulação'})}</div><div class="formrow">${select('Data no arquivo','file.dateFormat',c.file.dateFormat,{'DD/MM/AAAA':'Dia / mês / ano','AAAA-MM-DD':'Ano - mês - dia'})}${select('Separador decimal','file.decimal',c.file.decimal,{',':'Vírgula','.':'Ponto'})}</div>`:''}<div class="callout">${icon('file')}<span>Formato salvo como preferência. A importação será habilitada após validar o leitor com uma amostra de cada banco, incluindo saldos e possíveis repetições.</span></div>`}`}
  function routine(c){return `<div class="bank-form-heading"><h3>Atualização e conferência</h3><p>Defina a rotina desejada. O agendamento só começa após a conexão ser implementada e validada.</p></div><div class="formrow">${select('Frequência planejada','sync.frequency',c.sync.frequency,{manual:'Quando eu solicitar',daily:'Diariamente',twice:'Duas vezes ao dia (horário e +12h)'})}${input('Horário de referência','sync.time',c.sync.time,'time')}</div><p class="annotation">Fuso: America/Sao_Paulo. Para arquivos, a rotina serve como referência de organização.</p>${input('Consultar a partir de','sync.startDate',c.sync.startDate,'date')}<div class="formrow">${input('Reler os últimos dias','sync.overlapDays',c.sync.overlapDays,'number','min="1" max="30"')}${input('Janela de datas para sugestões (dias)','sync.matchDays',c.sync.matchDays,'number','min="0" max="30"')}</div><div class="bank-rules"><h3>Regras de conferência</h3><p>${icon('check')} Reimportar preservando o identificador bancário quando disponível.</p><p>${icon('check')} Revisar possíveis duplicatas quando a identificação for ambígua.</p><p>${icon('check')} Separar futuros, efetivados, estornos e saldos.</p><p>${icon('check')} Sugerir vínculos; confirmar obrigação, parcela e composição.</p><p>${icon('check')} Manter a conferência do comprovante independente.</p></div><div class="callout">${icon('info')}<span>Data e valor ajudam a encontrar uma obrigação, mas não bastam para provar a correspondência. Recebimentos parciais e rateios precisam manter sua composição.</span></div>`}
  function readiness(c,x){const rows=preparation(c,new Date().toISOString().slice(0,10));return `<div class="bank-form-heading"><h3>O que falta para começar?</h3><p>Esta lista verifica o preenchimento, sem se comunicar com o banco.</p></div><div class="bank-checklist">${rows.map(r=>`<div>${icon(r.ready?'check':'clock')}<span>${r.label}<small>${r.external?'Depende da implementação e validação externa':r.ready?'Informado na prévia; não validado pelo banco':'A preencher / conferir'}</small></span>${pill(r.ready?'Informado':'Pendente',r.ready?'green':'amber')}</div>`).join('')}</div><div class="callout">${icon('lock')}<span>Estado da conexão: <strong>não conectado</strong>. Nenhuma consulta, importação ou pagamento foi executado.</span></div>${x?`<div class="drawer-actions">${btn('Criar tarefa de preparação',`data-bank-prepare="${esc(x.id)}"`,'','task')}${btn('Exportar configuração salva',`data-bank-export="${esc(x.id)}"`,'','download')}</div><p class="annotation">A tarefa e a exportação usam o cadastro já salvo. Salve antes para incluir alterações deste formulário.</p><div class="drawer-section"><h3>Tarefas desta conta</h3>${a.scope('tasks').filter(t=>t.bankAccount===x.id).map(t=>link(t.title,'task',t.id,t.done?'Concluída':a.fullDate(t.due),'task')).join('')||empty('Nenhuma tarefa vinculada','Transforme a preparação da conexão em uma próxima ação.')}</div>`:'<p class="annotation">Salve a conta para criar tarefas e exportar o cadastro.</p>'}`}
  function dialog(kind,id){ensureBanking(a.state);if(kind==='bank-task'){const x=owned(id);if(!x)return null;return {heading:'Preparar conexão bancária',body:a.formShell('Próxima ação para '+esc(x.name),'A tarefa fica na Home e na lista de tarefas, vinculada a esta conta.',`<label>Próxima ação<input name="title" required maxlength="120" value="Preparar conexão · ${esc(x.name)}"></label><label>Prazo<input name="due" type="date" required value="${a.dateContext||a.NOW}"></label><label>Responsável<input name="owner" value="Você" required maxlength="80"></label>`,'bank-task',x.id,'Criar tarefa')}}
    if(kind!=='bank-account')return null;const x=owned(id);if(id&&!x)return {heading:'Conta indisponível',body:empty('Conta de outra empresa','Selecione uma conta desta empresa.')};const d=draft(),c=d.config;
    return {heading:x?'Configurar conta · '+x.name:'Cadastrar conta bancária',wide:true,body:`<div class="bank-drawer-head"><div><span class="eyebrow">${esc(a.get('companies',a.company).name)}</span><h2>${esc(x?.label||'Nova conta')}</h2></div>${pill('Não conectado','amber')}</div><div class="profile-tabs bank-tabs">${[['identity','Conta'],['connection','Conexão'],['routine','Rotina'],['ready','Preparação']].map(([key,label])=>`<button data-bank-tab="${key}" class="${d.tab===key?'active':''}" aria-pressed="${d.tab===key}">${label}</button>`).join('')}</div><form class="form" data-form="bank-account" data-id="${esc(id||'')}">${d.tab==='identity'?identity(d,x):d.tab==='connection'?connection(c):d.tab==='routine'?routine(c):readiness(c,x)}<div class="form-error" role="alert"></div><div class="drawer-actions"><button class="btn primary" type="submit">Salvar cadastro da prévia</button>${btn('Cancelar','data-action="back"')}</div><p class="annotation">As alterações ficam neste navegador. Não informe senhas, tokens, chaves ou certificados reais.</p></form>`};
  }
  function click(d){
    if(d.bankTab){capture();draft().tab=d.bankTab;a.draw();return true}
    if(d.bankMode){capture();draft().config.mode=d.bankMode;a.draw();return true}
    if(d.bankPrepare){capture();a.open('bank-task',d.bankPrepare);return true}
    if(d.bankExport){const x=owned(d.bankExport);if(x){a.download('configuracao-bancaria-'+x.id+'.json',JSON.stringify(publicConfiguration(x),null,2),'application/json');a.toast('Configuração salva exportada. Credenciais reais não estão incluídas.')}return true}
    return false;
  }
  function change(e){if(!e.target.dataset.bankField)return false;const path=e.target.dataset.bankField;capture();if(path==='bankCode'){draft().config.environments=newBanking().environments}if(['bankCode','holderType','environment','file.format'].includes(path))a.draw();return true}
  function submit(form,data){
    if(form.dataset.form==='bank-task'){const x=owned(form.dataset.id);if(!x)return true;a.state.tasks.push({id:'t-'+crypto.randomUUID(),company:a.company,title:String(data.get('title')).trim(),due:String(data.get('due')),owner:String(data.get('owner')).trim(),kind:'Conexão bancária',bankAccount:x.id,done:false});a.save();a.closeAll();a.render();a.toast('Tarefa criada e vinculada à conta.');return true}
    if(form.dataset.form!=='bank-account')return false;capture(form);const d=draft(),c=d.config;c.taxId=normalizeTaxId(c.taxId);c.digit=c.digit.toUpperCase();c.branchDigit=c.branchDigit.toUpperCase();const errors=validateDraft(c,d.label);const clean=v=>v.replace(/^0+(?=\d)/,'');if(c.branch&&c.number&&a.scope('accounts').some(x=>x.id!==form.dataset.id&&x.banking.bankCode===c.bankCode&&x.banking.type===c.type&&clean(x.banking.branch)===clean(c.branch)&&clean(x.banking.number)===clean(c.number)))errors.push('Esta agência e conta já estão cadastradas nesta empresa. Abra o cadastro existente.');if(errors.length){form.querySelector('.form-error').textContent=errors.join(' ');return true}let x=owned(form.dataset.id);if(form.dataset.id&&!x)return true;if(!x){x={id:'account-'+crypto.randomUUID(),company:a.company,opening:0};a.state.accounts.push(x)}x.label=d.label.trim();x.name=BANKS[c.bankCode].name;x.banking=structuredClone(c);a.save();a.closeAll();a.navigate('banks');a.toast('Cadastro salvo na prévia. Nenhuma conexão foi ativada.');return true;
  }
  return {page,dialog,click,change,submit};
}
